		3660.0, 3436.0, 3101.0, 2646.0, 2456.0, 2256.0, 2172.0, 2016.0, 1834.0, 1742.0, 1660.0, 1596.0, 1457.0, 1350.0, 1160.0, 1063.0, 818.0, 711.0, 451.0, 181.0, 54.0, 21.0, 0.0,                   &
		3803.0, 3603.0, 3229.0, 2831.0, 2608.0, 2447.0, 2288.0, 2165.0, 1973.0, 1880.0, 1808.0, 1726.0, 1603.0, 1482.0, 1300.0, 1184.0, 939.0, 793.0, 492.0, 199.0, 61.0, 24.0, 0.0,                   &
		3955.0, 3698.0, 3320.0, 2917.0, 2733.0, 2544.0, 2379.0, 2256.0, 2073.0, 1965.0, 1884.0, 1823.0, 1695.0, 1572.0, 1379.0, 1277.0, 1038.0, 867.0, 544.0, 221.0, 70.0, 28.0, 0.0,                  &
		4116.0, 3784.0, 3378.0, 2975.0, 2801.0, 2599.0, 2485.0, 2355.0, 2203.0, 2056.0, 1990.0, 1903.0, 1780.0, 1652.0, 1478.0, 1334.0, 1100.0, 924.0, 579.0, 239.0, 78.0, 32.0, 0.0,                  &
		4275.0, 3839.0, 3393.0, 2985.0, 2850.0, 2658.0, 2529.0, 2447.0, 2294.0, 2117.0, 2050.0, 1971.0, 1835.0, 1693.0, 1523.0, 1373.0, 1163.0, 969.0, 601.0, 254.0, 85.0, 35.0, 0.0,                  &
		4471.0, 3887.0, 3394.0, 3000.0, 2880.0, 2700.0, 2589.0, 2496.0, 2361.0, 2216.0, 2129.0, 2033.0, 1872.0, 1737.0, 1566.0, 1403.0, 1214.0, 1003.0, 640.0, 272.0, 91.0, 39.0, 0.0,                 &
		4689.0, 3970.0, 3405.0, 3030.0, 2900.0, 2740.0, 2598.0, 2498.0, 2410.0, 2287.0, 2170.0, 2067.0, 1902.0, 1790.0, 1622.0, 1439.0, 1260.0, 1026.0, 667.0, 290.0, 96.0, 42.0, 0.0/
!  
!---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
!
      mflux_a=DMIN1(7500.d0,mflux_tota)
      mflux=DSIGN(mflux_a,vg_n(i,f_direc))                   !!!cyj: must check how to define 'node direction & elevation change' in MARS code
      pm=cell%p(i)*1.0d-6                                   ! Pressure in MPa
      x=DMIN1(1.0d0,DMAX1(-0.5d0,qual_eq))
      hfga=hfg_p
      rhol=cell%rhol(i)
      rhog=cell%rhog(i)
      dr=DMAX1(1.d-5,rhol-rhog)
!
!.....CHF for Reflood option (Zuber Correlation)
!  
      IF(reflood.ge.1)THEN
         IF(mflux_a.lt.ghigh)THEN
            zuber=0.13d0*hfg_p*sqrt(rhog*sqrt(gravity*cell%sigma(i)*dr))
!            zuber=zuber*DMAX1(cell%alphal(i),0.04d0)
            zuber=zuber*DMAX1(1.0d0-cell%alphag(i),0.04d0) ! yjm
            IF(mflux_a.le.glow)THEN
               chf=zuber
               chf_mul=1.0d0
               GOTO 910
            ENDIF
         ENDIF
      ENDIF      
!
!.....Extrapolation for outside pressure range:If pressure is outside the range of .1-20. MPa use properties ratioing to adjust CHF.
!                                                
      IF(pm.gt.ptab(1).and.pm.lt.ptab(15))THEN 
!        k8: the pressure ratio factor for pressures outside the table. 
         k8=1.d0 
      ELSE                                     
         IF(pm.lt.ptab(1))THEN 
            pm=ptab(1) 
!           at a pressure of 1MPa: sigma = 0.05885, rhof= 958.38, rhog= 0.5904, hfg= 2.257923e6, hfg*dsqrt(rhog*dsqrt(sigma*(rhof-rhog)))=4.7534e6              
!           denom1= 1./4.7534e6 =  2.10375e-7                            
            denom1=2.10375d-7 
         ELSE 
            pm=ptab(15) 
!           at a pressure of 20 MPa:sigma = 0.0011108, rhof=490.9, rhog=170.16, hfg=591880.     ,hfg*dsqrt(rhog*dsqrt(sigma*(rhof-rhog)))=5.964989e6            
!            denom1= 1./5.964989e6 = 1.6764e-7                            
            denom1=1.6764d-7 
         ENDIF 
!         k8=hfga*DSQRT(rhog*DSQRT(sigma*DABS(rhol-rhog)))*denom1                                                         
         k8=hfga*DSQRT(rhog*DSQRT(sigma*dr))*denom1                                                         
      ENDIF       
!==========================================================================================================================
!
!.....Calculate multiflier for CHF
!
!==========================================================================================================================
!
!.....k1 : diameter correction factor for other than rod_diameter=0.008m (ref : Nuclear technology, 2005 by Groeneveld)
!
      IF(dia_rod.lt.0.003d0)THEN   
         k1 = 1.632993d0;     !k1=(0.008/0.003)^0.5=1.633    for D<0.003m
      ELSEIF(dia_rod.lt.0.025d0) THEN
         k1=(.008d0/dia_rod)**0.5d0 
      ELSE 
         k1=.5656854d0        !k1=(0.008/0.025)^0.5=0.57     for D>0.025m
      ENDIF 
!
!.....k2: for rod bundles (ref : latest correction factor, NURETH-9, 1999 by Groeneveld)     
!      
      IF(inline_bundle.eq.1)THEN 
         a=DMAX1(0.d0,x)
         k2=DMIN1(1.0d0,(0.5d0+2.0d0*pit_dia)*DEXP(-0.5d0*a**.3333d0)) 
      ELSE 
         k2=1.d0 
      ENDIF
!       
!.....k3: for grid spacer effects
!
      IF(k_grid.eq.0.d0)then 
         k3=1.d0 
      ELSE 
         a=1.5d0*DSQRT(k_grid)*(mflux_a*.001d0)**0.2d0 
         k3=1.d0+a*DEXP(-0.1d0*dis_grid/dia_rod) 
      ENDIF 
!      
!.....k4: the heated length factor                                    
!
      a=DMIN1(1.d0,DMAX1(0.d0,x)) 
      alp=a/(a+rhog*(1.d0-a)/rhol) 
      IF(h_bundle.eq.0.d0) THEN 
         k4=1.d0
      ELSE
         k4=DEXP(DMIN1(dia_rod/h_bundle,0.2d0)*DEXP(2.d0*alp)) 
      ENDIF   
!      
!.....k5: the axial flux profile factor                               
!
      IF(x.lt.0.d0)then 
         k5=1.d0 
      ELSE 
         k5=f_pp_axial 
      ENDIF 
      k7=1.d0
!      
!.....Find pressure interpolation points
!
      ip=ipold 
      pt=ptab(ip) 
      ptm1=ptab(ip-1) 
      IF(pm.ge.ptm1.and.pm.le.pt) GOTO 19 
      IF(pm.lt.ptm1)THEN 
         ipold=ipold-1 
         DO 10 k=ipold,2,-1 
            ip=k 
            IF(pm.ge.ptab(k-1)) GOTO 19 
   10    END DO 
      ELSE 
         ipold=ipold+1 
         DO 15 k=ipold,15 
            ip=k 
            IF(pm.le.ptab(k)) GOTO 19 
   15    END DO 
      ENDIF 
   19 CONTINUE 
      ipold=ip 
!
!.....Find quality interpolation points                                     
!
      ix=ixold 
      xt=xtab(ix) 
      xtm1=xtab(ix-1) 
      IF(x.ge.xtm1.and.x.le.xt) GOTO 29 
      IF(x.lt.xtm1)THEN 
         ixold=ixold-1 
         DO 20 k=ixold,2,-1 
            ix=k 
            IF(x.ge.xtab(k-1)) GOTO 29 
   20    END DO 
      ELSE 
         ixold=ixold+1 
         DO 25 k=ixold,21 
            ix=k 
            IF(x.le.xtab(k)) GOTO 29 
   25    END DO 
      ENDIF 
   29 CONTINUE 
      ixold=ix 
!
!.....Find mass flux interpolation points                                   
!
      ig=igold 
      gt=gtab(ig) 
      gtm1=gtab(ig-1) 
      IF(mflux_a.ge.gtm1.and.mflux_a.le.gt) GOTO 39 
      IF(mflux_a.lt.gtm1)THEN 
         igold=igold-1 
         DO 30 k=igold,2,-1 
            ig=k 
            IF(mflux_a.ge.gtab(k-1)) GOTO 39 
   30    END DO 
      ELSE 
         igold=igold+1 
         DO 35 k=igold,16 
            ig=k 
            IF(mflux_a.le.gtab(k)) GOTO 39 
   35    END DO 
      ENDIF 
   39 CONTINUE 
      igold=ig 
!      
! the three upper p,g,x points have been found in the table             
!  now do the interpolation to find the critical heat flux.             
! after setting the vertical flow factor k7 to 1.                       
! Use volume void instead of equilibrium void for K7.                   
!
!.....k6: the horizontal flow factor
!                                 
      IF(horiz_chf.ne.1)then 
         k6=1.d0 
      ELSE 
         IF(cell%alphal(i).gt.0.5d0)then 
            !angle_horiz=htheta(cell%alphal(i)) 
            k6=1.0d0-angle_horiz/pi 
         ELSE 
            !angle_horiz=htheta(cell%alphal(i)) 
            k6=angle_horiz/pi 
         ENDIF 
         GOTO 40 
      ENDIF 
!      
!..... Interpoate for pressure, mass flux, and qulaity                                                         
!      Groeneveld says interpolate if -400<g<-50 or 10<g<100 unless the quality .le. 0 for vertical flow
!
      IF(x.le.0.d0) GOTO 40 
      IF(mflux.le.-400.d0.or.mflux.ge.100.d0) GOTO 40 
!     
      IF(cell%alphag(i).lt.0.8d0)then 
         k7=1.d0 
      ELSE 
         k7=(0.8d0+0.2d0*rhol/rhog)/(cell%alphag(i)+(1.d0-cell%alphag(i))*rhol/rhog) 
      ENDIF 
      k7=k7*(1.d0-cell%alphag(i)) 
!
      IF(mflux.ge.-50.d0.and.mflux.le.10.d0)then 
         chf=hinter(ptab(ip),ptab(ip-1),qtab(ip,1,8),qtab(ip-1,1,8),pm) 
         chf=chf*k7 
         GOTO 900 
      ENDIF 
!   
      IF(mflux.lt.0.d0)then 
!        for -400<g<-50; c2,c4 are at g=0(ig=1),x=0(ix=8); c1,c3 at -400(ig=7) 
         c1=hinter(ptab(ip),ptab(ip-1),qtab(ip,7,ix),qtab(ip-1,7,ix),pm) 
         c2=hinter(ptab(ip),ptab(ip-1),qtab(ip,1,8),qtab(ip-1,1,8),pm) 
         c2=c2*k7 
         c3=hinter(ptab(ip),ptab(ip-1),qtab(ip,7,ix-1),qtab(ip-1,7,ix-1)&
         ,pm)                                                           
         c4=c2 
         c5=hinter(400.d0,50.d0,c1,c2,mflux_a) 
         c6=hinter(400.d0,50.d0,c3,c4,mflux_a) 
         chf=hinter(xtab(ix),xtab(ix-1),c5,c6,x) 
         GOTO 900 
      ELSE 
!        for 10<g<100; c1,c3 are at 100(ig=4); c2,c4 are at g=0(ig=1),x=0(ix=8)
         c1=hinter(ptab(ip),ptab(ip-1),qtab(ip,4,ix),qtab(ip-1,4,ix),pm) 
         c2=hinter(ptab(ip),ptab(ip-1),qtab(ip,1,8),qtab(ip-1,1,8),pm) 
         c2=c2*k7 
         c3=hinter(ptab(ip),ptab(ip-1),qtab(ip,4,ix-1),qtab(ip-1,4,ix-1)&
         ,pm)                                                           
         c4=c2 
         c5=hinter(100.d0,10.d0,c1,c2,mflux_a) 
         c6=hinter(100.d0,10.d0,c3,c4,mflux_a) 
         chf=hinter(xtab(ix),xtab(ix-1),c5,c6,x) 
      ENDIF 
      
      GOTO 900 
   40 CONTINUE 
!   
!.....Interpolation for High mass flux
!
      c1=hinter(ptab(ip),ptab(ip-1),qtab(ip,ig,ix),qtab(ip-1,ig,ix),pm) 
      c2=hinter(ptab(ip),ptab(ip-1),qtab(ip,ig-1,ix),qtab(ip-1,ig-1,ix),pm)                                                               
      c3=hinter(ptab(ip),ptab(ip-1),qtab(ip,ig,ix-1),qtab(ip-1,ig,ix-1),pm)                                                               
      c4=hinter(ptab(ip),ptab(ip-1),qtab(ip,ig-1,ix-1),qtab(ip-1,ig-1,ix-1),pm)                                                         
      c5=hinter(gtab(ig),gtab(ig-1),c1,c2,mflux_a) 
      c6=hinter(gtab(ig),gtab(ig-1),c3,c4,mflux_a) 
      chf=hinter(xtab(ix),xtab(ix-1),c5,c6,x) 
      zuber=0.0d0
  900 CONTINUE   
!
!.....Final CHF value 
!  
      chf_mul=k1*k2*k3*k4*k5*k6*k8 
      chf=chf*chf_mul 
      chf_mul=chf_mul*k7 
      chf=chf * 1.d3                 !Unit conversion: kW/m2 -> W/m2
!
!.....CHF for Reflood option (Zuber Correlation)
!  
      IF(reflood.ge.1)THEN
         IF(mflux_a.lt.ghigh)THEN
            IF(mflux_a.gt.glow)THEN    
               difcc=1.0d0/(ghigh-glow)
               chf=(mflux_a-glow)*chf*difcc+(ghigh-mflux_a)*zuber*difcc
            ENDIF                
         ENDIF
      ENDIF       
  910 CONTINUE      
!
      RETURN     
      END SUBROUTINE CHF_calc
